import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"28、【大过】 巽下兑上","description":"温公易说 - 28、【大过】 巽下兑上","frontmatter":{"title":"28、【大过】 巽下兑上","description":"温公易说 - 28、【大过】 巽下兑上"},"headers":[],"relativePath":"zh/classics/wengong/029.md","filePath":"zh/classics/wengong/029.md"}'),n={name:"zh/classics/wengong/029.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_28、【大过】-巽下兑上" tabindex="-1">28、【大过】 巽下兑上 <a class="header-anchor" href="#_28、【大过】-巽下兑上" aria-label="Permalink to “28、【大过】 巽下兑上”">​</a></h1><h3 id="彖曰-大过-大者过也。栋桡-本末弱也。刚过而中-巽而说-行利有攸往-乃亨。大过之时-大矣哉。" tabindex="-1">彖曰：大过，大者过也。栋桡，本末弱也。刚过而中，巽而说，行利有攸往，乃亨。大过之时，大矣哉。 <a class="header-anchor" href="#彖曰-大过-大者过也。栋桡-本末弱也。刚过而中-巽而说-行利有攸往-乃亨。大过之时-大矣哉。" aria-label="Permalink to “彖曰：大过，大者过也。栋桡，本末弱也。刚过而中，巽而说，行利有攸往，乃亨。大过之时，大矣哉。”">​</a></h3><p>大过者何？大者阳也。阳之过差者也。阳之所以过差者奈何？阳当居外以卫阴，阴当居内以佐阳。今大过多阳而居内，小过多阴而居外，此其所以为过也。然则彖曰刚过而中，巽而说，行利有攸往，乃亨何也？大过者，刚之过也。有攸往者，犹云有为而然者也。夫刚过而不得其中，又不以巽说行之，其志非以有为也，茍求过人而已矣。如是则何以得亨乎？故大过之所以得亨者，此数德故也。君子或为过人之行者，将以有为也，非道之常也。故曰利有攸往，乃亨。</p><h3 id="象曰-泽灭木-大过。君子以独立不惧-遁世无闷。" tabindex="-1">象曰：泽灭木，大过。君子以独立不惧，遁世无闷。 <a class="header-anchor" href="#象曰-泽灭木-大过。君子以独立不惧-遁世无闷。" aria-label="Permalink to “象曰：泽灭木，大过。君子以独立不惧，遁世无闷。”">​</a></h3><h3 id="初六-藉用白茅-无咎-象曰-藉用白茅-柔在下也。" tabindex="-1">初六：藉用白茅，无咎 象曰：藉用白茅，柔在下也。 <a class="header-anchor" href="#初六-藉用白茅-无咎-象曰-藉用白茅-柔在下也。" aria-label="Permalink to “初六：藉用白茅，无咎 象曰：藉用白茅，柔在下也。”">​</a></h3><h3 id="九二-枯杨生稊-老夫得其女妻-无不利-象曰-老夫女妻-过以相与也。" tabindex="-1">九二：枯杨生稊，老夫得其女妻，无不利 象曰：老夫女妻，过以相与也。 <a class="header-anchor" href="#九二-枯杨生稊-老夫得其女妻-无不利-象曰-老夫女妻-过以相与也。" aria-label="Permalink to “九二：枯杨生稊，老夫得其女妻，无不利 象曰：老夫女妻，过以相与也。”">​</a></h3><h3 id="九三-栋桡-凶-象曰-栋桡之凶-不可有辅也。" tabindex="-1">九三：栋桡，凶 象曰：栋桡之凶，不可有辅也。 <a class="header-anchor" href="#九三-栋桡-凶-象曰-栋桡之凶-不可有辅也。" aria-label="Permalink to “九三：栋桡，凶 象曰：栋桡之凶，不可有辅也。”">​</a></h3><h3 id="九四-栋隆-吉。有它吝-象曰-栋隆之吉-不桡乎下也。" tabindex="-1">九四：栋隆，吉。有它吝 象曰：栋隆之吉，不桡乎下也。 <a class="header-anchor" href="#九四-栋隆-吉。有它吝-象曰-栋隆之吉-不桡乎下也。" aria-label="Permalink to “九四：栋隆，吉。有它吝 象曰：栋隆之吉，不桡乎下也。”">​</a></h3><h3 id="九五-枯杨生华-老妇得其士夫-无咎-无誉-象曰-枯杨生华-何可久也。老妇士夫-亦可丑也。" tabindex="-1">九五：枯杨生华，老妇得其士夫，无咎，无誉 象曰：枯杨生华，何可久也。老妇士夫，亦可丑也。 <a class="header-anchor" href="#九五-枯杨生华-老妇得其士夫-无咎-无誉-象曰-枯杨生华-何可久也。老妇士夫-亦可丑也。" aria-label="Permalink to “九五：枯杨生华，老妇得其士夫，无咎，无誉 象曰：枯杨生华，何可久也。老妇士夫，亦可丑也。”">​</a></h3><h3 id="上六-过涉灭顶-凶-无咎-象曰-过涉之凶-不可咎也。" tabindex="-1">上六：过涉灭顶，凶，无咎 象曰：过涉之凶，不可咎也。 <a class="header-anchor" href="#上六-过涉灭顶-凶-无咎-象曰-过涉之凶-不可咎也。" aria-label="Permalink to “上六：过涉灭顶，凶，无咎 象曰：过涉之凶，不可咎也。”">​</a></h3>',10)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
